<script setup lang="ts">
import { useRichTextEditor } from "../../composables/useRichTextEditor";
import { usePopoverRoot } from "../../composables/usePopoverRoot";
import type { ParagraphBlock as ParagraphBlockType } from "@templatical/types";
import ParagraphToolbar from "./ParagraphToolbar.vue";
import RichTextLinkDialog from "./RichTextLinkDialog.vue";
import RichTextEditorContent from "./RichTextEditorContent.vue";
import { withLinkColor } from "../../utils/linkColorExtension";

const props = defineProps<{
  block: ParagraphBlockType;
  toolbarPosition: { top: number; left: number };
}>();

const emit = defineEmits<{
  (e: "done"): void;
}>();

const popoverRoot = usePopoverRoot();

const {
  editor,
  EditorContent,
  isLoading,
  initError,
  retry,
  showLinkDialog,
  linkUrl,
  linkColor,
  linkDialogRef,
  canRequestMergeTag,
  canInsertLogicTag,
  openLinkDialog,
  insertLink,
  removeLink,
  closeLinkDialog,
  handleLinkKeydown,
  handleAddMergeTag,
  handleAddLogicTag,
} = useRichTextEditor({
  blockId: () => props.block.id,
  blockContent: () => props.block.content,
  onDone: () => emit("done"),
  editorName: "ParagraphEditor",
  async loadExtensions({
    mergeTags,
    syntax,
    triggerChar,
    autocompleteEnabled,
    suggestionEmptyText,
  }) {
    const [
      { Editor: TiptapEditor, EditorContent: EC },
      { default: StarterKit },
      { default: LinkExt },
      { default: UnderlineExt },
      { default: SubscriptExt },
      { default: SuperscriptExt },
      { default: TextAlign },
      { TextStyle },
      { default: Color },
      { default: FontFamily },
      { default: Highlight },
      {
        MergeTagNode,
        MergeTagSuggestion,
        LogicMergeTagNode,
        FontSize,
        LineHeight,
        LetterSpacing,
      },
    ] = await Promise.all([
      import("@tiptap/vue-3"),
      import("@tiptap/starter-kit"),
      import("@tiptap/extension-link"),
      import("@tiptap/extension-underline"),
      import("@tiptap/extension-subscript"),
      import("@tiptap/extension-superscript"),
      import("@tiptap/extension-text-align"),
      import("@tiptap/extension-text-style"),
      import("@tiptap/extension-color"),
      import("@tiptap/extension-font-family"),
      import("@tiptap/extension-highlight"),
      import("../../extensions"),
    ]);

    return {
      TiptapEditor,
      EC,
      extensions: [
        StarterKit.configure({
          heading: false,
          codeBlock: false,
          blockquote: false,
          horizontalRule: false,
          // StarterKit bundles @tiptap/extension-link (openOnClick: true).
          // Disable it so the LinkExt below (openOnClick: false) is the only
          // link extension — otherwise clicking a link while editing opens it.
          link: false,
          // StarterKit also bundles @tiptap/extension-underline; the editor
          // registers its own UnderlineExt below, so disable StarterKit's copy
          // to avoid a duplicate `underline` extension (and its console warning).
          underline: false,
        }),
        UnderlineExt,
        SubscriptExt,
        SuperscriptExt,
        withLinkColor(LinkExt).configure({
          openOnClick: false,
          HTMLAttributes: {
            target: "_blank",
            rel: "noopener noreferrer",
          },
        }),
        TextAlign.configure({ types: ["paragraph"] }),
        TextStyle,
        Color,
        FontFamily,
        Highlight.configure({ multicolor: true }),
        FontSize,
        LineHeight,
        LetterSpacing,
        MergeTagNode.configure({ mergeTags, syntax }),
        LogicMergeTagNode.configure({ syntax }),
        ...(autocompleteEnabled && triggerChar && mergeTags.length > 0
          ? [
              MergeTagSuggestion.configure({
                mergeTags,
                char: triggerChar,
                emptyText: suggestionEmptyText,
                popoverRoot,
              }),
            ]
          : []),
      ],
    };
  },
});
</script>

<template>
  <div class="tpl-text-editor-wrapper tpl:relative">
    <ParagraphToolbar
      :editor="editor"
      :toolbar-position="toolbarPosition"
      :is-loading="isLoading"
      :can-request-merge-tag="canRequestMergeTag"
      :can-insert-logic-tag="canInsertLogicTag"
      @open-link-dialog="openLinkDialog"
      @add-merge-tag="handleAddMergeTag"
      @add-logic-tag="handleAddLogicTag"
    />

    <RichTextEditorContent
      :editor="editor"
      :editor-content="EditorContent"
      :is-loading="isLoading"
      :init-error="initError"
      @retry="retry"
    />

    <RichTextLinkDialog
      :visible="showLinkDialog"
      :is-editing-link="editor?.isActive('link') ?? false"
      v-model:dialog-ref="linkDialogRef"
      v-model:link-url="linkUrl"
      v-model:link-color="linkColor"
      @close="closeLinkDialog"
      @insert="insertLink"
      @remove="removeLink"
      @keydown="handleLinkKeydown"
    />
  </div>
</template>
